// ============================================
// NODO 1: PARSEAR ENTRADA DEL USUARIO
// ============================================
// Formato esperado: "keyword, idioma"
// Ejemplos:
//   "hoteles baratos en managua, es"
//   "cheap hotels london, en"
//   "hoteles managua" (default: español)
// ============================================

const input = $input.first().json.chatInput || $input.first().json.text || '';

// Separar keyword e idioma por coma
const parts = input.split(',').map(s => s.trim());
const keyword = parts[0] || '';
const langInput = (parts[1] || 'es').toLowerCase();

// Mapeo flexible de idiomas
const langMap = {
  'es': 'es', 'español': 'es', 'spanish': 'es', 'espanol': 'es',
  'en': 'en', 'inglés': 'en', 'english': 'en', 'ingles': 'en',
  'fr': 'fr', 'francés': 'fr', 'french': 'fr', 'frances': 'fr',
  'pt': 'pt', 'portugués': 'pt', 'portuguese': 'pt', 'portugues': 'pt',
  'de': 'de', 'alemán': 'de', 'german': 'de', 'aleman': 'de',
  'it': 'it', 'italiano': 'it', 'italian': 'it'
};

const hl = langMap[langInput] || langInput.substring(0, 2);

if (!keyword) {
  return [{
    json: {
      error: true,
      output: '❌ Formato: escribe una keyword seguida de coma y el idioma.\n\nEjemplos:\n• hoteles baratos en managua, es\n• cheap hotels in london, en\n• restaurants paris, fr'
    }
  }];
}

return [{
  json: {
    keyword: keyword,
    language: hl,
    originalInput: input
  }
}];

// ============================================
// NODO 2: GENERAR VARIACIONES A-Z
// ============================================
// Crea 27 variaciones de la keyword:
// - La keyword original (sin letra)
// - keyword + " a", keyword + " b", ..., keyword + " z"
// Cada una se enviará a Google Suggest = ~270 keywords
// ============================================

const keyword = $input.first().json.keyword;
const language = $input.first().json.language;

// Generar la keyword original + 26 variaciones con letras
const letters = ['', ...'abcdefghijklmnopqrstuvwxyz'.split('')];

const variations = letters.map(letter => ({
  json: {
    searchQuery: letter ? `${keyword} ${letter}` : keyword,
    originalKeyword: keyword,
    language: language,
    letter: letter || 'original'
  }
}));

return variations;

// ============================================
// NODO 3: EXTRAER TODAS LAS KEYWORDS DE GOOGLE
// ============================================
// Recoge TODAS las respuestas del loop y extrae
// las sugerencias en una lista plana.
// Elimina duplicados.
// ============================================

const allItems = $input.all();
const keywordsSet = new Set();
let originalKeyword = '';
let language = 'es';

for (const item of allItems) {
  const data = item.json;

  // Intentar capturar originalKeyword y language
  if (data.originalKeyword) originalKeyword = data.originalKeyword;
  if (data.language) language = data.language;

  // La respuesta HTTP puede venir en varios formatos
  let rawText = data.data || data.body || '';

  // Si es un objeto, intentar stringificar
  if (typeof rawText === 'object') {
    rawText = JSON.stringify(rawText);
  }

  try {
    // Buscar el array JSON en la respuesta
    const text = String(rawText);
    const startIdx = text.indexOf('[');
    const endIdx = text.lastIndexOf(']') + 1;

    if (startIdx >= 0 && endIdx > startIdx) {
      const parsed = JSON.parse(text.substring(startIdx, endIdx));

      if (Array.isArray(parsed) && Array.isArray(parsed[1])) {
        for (const suggestion of parsed[1]) {
          if (typeof suggestion === 'string' && suggestion.trim()) {
            keywordsSet.add(suggestion.trim().toLowerCase());
          }
        }
      }
    }
  } catch (e) {
    // Ignorar errores de parsing individual
  }
}

// Convertir Set a array de items
const keywords = [...keywordsSet];

if (keywords.length === 0) {
  return [{
    json: {
      source: 'google',
      keyword: 'Sin resultados de Google',
      originalKeyword: originalKeyword,
      language: language
    }
  }];
}

return keywords.map((kw, i) => ({
  json: {
    source: 'google',
    keyword: kw,
    originalKeyword: originalKeyword,
    language: language,
    index: i + 1
  }
}));

// ============================================
// NODO 4: PARSEAR RESPUESTA DE OPENAI
// ============================================
// Extrae el array JSON de keywords de la
// respuesta de ChatGPT
// ============================================

const response = $input.first().json;

// El texto puede estar en diferentes campos según versión del nodo
let text = response.text || response.content || response.message?.content || '';

// Si es un array de content blocks
if (Array.isArray(response.content)) {
  text = response.content
    .filter(b => b.type === 'text')
    .map(b => b.text)
    .join('');
}

const originalKeyword = $('Parsear Entrada').first().json.keyword;
const language = $('Parsear Entrada').first().json.language;

let keywords = [];

try {
  // Limpiar el texto: quitar markdown code blocks si los hay
  let cleanText = text
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  // Encontrar el array JSON
  const startIdx = cleanText.indexOf('[');
  const endIdx = cleanText.lastIndexOf(']') + 1;

  if (startIdx >= 0 && endIdx > startIdx) {
    keywords = JSON.parse(cleanText.substring(startIdx, endIdx));
  }
} catch (e) {
  // Fallback: intentar extraer líneas como keywords
  keywords = text.split('\n')
    .map(line => line.replace(/^[\d\-\*\.\)]+\s*/, '').trim())
    .filter(line => line.length > 3 && line.length < 100);
}

if (keywords.length === 0) {
  return [{
    json: {
      source: 'openai',
      keyword: 'Sin resultados de OpenAI',
      originalKeyword: originalKeyword,
      language: language
    }
  }];
}

return keywords.map((kw, i) => ({
  json: {
    source: 'openai',
    keyword: String(kw).trim().toLowerCase(),
    originalKeyword: originalKeyword,
    language: language,
    index: i + 1
  }
}));

// ============================================
// NODO 5: ELIMINAR DUPLICADOS
// ============================================
// Combina keywords de Google + OpenAI
// y elimina duplicados por texto normalizado
// ============================================

const allItems = $input.all();
const seen = new Map(); // keyword normalizada -> item original

for (const item of allItems) {
  const kw = (item.json.keyword || '').trim().toLowerCase();

  if (kw && kw.length > 2 && !kw.includes('sin resultado')) {
    if (!seen.has(kw)) {
      seen.set(kw, item.json);
    } else {
      // Si ya existe, marcar que viene de ambas fuentes
      const existing = seen.get(kw);
      if (existing.source !== item.json.source) {
        existing.source = 'google+openai';
      }
    }
  }
}

const uniqueKeywords = [...seen.values()];

return uniqueKeywords.map((data, i) => ({
  json: {
    ...data,
    index: i + 1,
    totalKeywords: uniqueKeywords.length
  }
}));

// ============================================
// NODO 6: PREPARAR LOTE PARA CLASIFICACIÓN
// ============================================
// Agrupa TODAS las keywords en un solo texto
// para enviar a OpenAI en UNA sola llamada
// (más eficiente que clasificar una por una)
// ============================================

const allItems = $input.all();
const keywords = allItems.map(item => item.json.keyword);

// Crear un JSON array de todas las keywords
const keywordsList = JSON.stringify(keywords);

return [{
  json: {
    keywordsList: keywordsList,
    keywordsArray: keywords,
    totalCount: keywords.length,
    originalKeyword: allItems[0]?.json?.originalKeyword || '',
    language: allItems[0]?.json?.language || 'es',
    // Guardar el mapping source para cada keyword
    sourcesMap: JSON.stringify(
      Object.fromEntries(
        allItems.map(item => [item.json.keyword, item.json.source || 'unknown'])
      )
    )
  }
}];

// ============================================
// NODO 7: FORMATEAR RESULTADO FINAL
// ============================================
// Combina la clasificación de OpenAI con
// la info de fuente (Google/OpenAI/ambos)
// y genera una lista completa y bonita
// ============================================

const classifyResponse = $input.first().json;
const prepData = $('Preparar para Clasificar').first().json;

// Obtener la respuesta de clasificación
let responseText = classifyResponse.text || classifyResponse.content || '';
if (Array.isArray(classifyResponse.content)) {
  responseText = classifyResponse.content
    .filter(b => b.type === 'text')
    .map(b => b.text)
    .join('');
}

// Parsear la clasificación
let classified = [];
try {
  const cleanText = responseText
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  const startIdx = cleanText.indexOf('[');
  const endIdx = cleanText.lastIndexOf(']') + 1;

  if (startIdx >= 0 && endIdx > startIdx) {
    classified = JSON.parse(cleanText.substring(startIdx, endIdx));
  }
} catch (e) {
  // Si falla el parsing, usar las keywords sin clasificar
  const keywords = JSON.parse(prepData.keywordsArray || '[]');
  classified = keywords.map(kw => ({
    keyword: kw,
    tipo: 'SIN CLASIFICAR',
    subtipo: 'error parsing'
  }));
}

// Obtener mapa de fuentes
let sourcesMap = {};
try {
  sourcesMap = JSON.parse(prepData.sourcesMap || '{}');
} catch (e) {}

// Agrupar por tipo
const grupos = {};
for (const item of classified) {
  const tipo = item.tipo || 'SIN CLASIFICAR';
  if (!grupos[tipo]) grupos[tipo] = [];

  const source = sourcesMap[item.keyword] || sourcesMap[item.keyword?.toLowerCase()] || '?';
  const sourceEmoji = source === 'google' ? '🔍' : source === 'openai' ? '🤖' : source === 'google+openai' ? '🔍🤖' : '•';

  grupos[tipo].push({
    keyword: item.keyword,
    subtipo: item.subtipo || '',
    source: sourceEmoji
  });
}

// Contar totales
const totalKeywords = classified.length;
const fromGoogle = Object.values(sourcesMap).filter(s => s === 'google' || s === 'google+openai').length;
const fromOpenAI = Object.values(sourcesMap).filter(s => s === 'openai' || s === 'google+openai').length;
const fromBoth = Object.values(sourcesMap).filter(s => s === 'google+openai').length;

// Construir la respuesta formateada
let output = `# 🔎 Keyword Research: "${prepData.originalKeyword}"\n\n`;
output += `## 📊 Resumen\n`;
output += `- **Total keywords encontradas:** ${totalKeywords}\n`;
output += `- **De Google Suggest (A-Z):** ${fromGoogle} 🔍\n`;
output += `- **De OpenAI/ChatGPT:** ${fromOpenAI} 🤖\n`;
output += `- **Coinciden en ambas fuentes:** ${fromBoth} 🔍🤖\n`;
output += `- **Idioma:** ${prepData.language}\n\n`;
output += `---\n\n`;

// Orden de prioridad para mostrar tipos
const ordenTipos = [
  'COMPRA', 'COMPRA + LOCAL', 
  'INVESTIGACION', 'INVESTIGACION + LOCAL',
  'LOCAL', 
  'INFORMATIVA', 
  'NAVEGACIONAL',
  'SIN CLASIFICAR'
];

// Mostrar grupos en orden
const tiposPresentes = [...new Set([...ordenTipos.filter(t => grupos[t]), ...Object.keys(grupos)])];

for (const tipo of tiposPresentes) {
  if (!grupos[tipo] || grupos[tipo].length === 0) continue;

  const items = grupos[tipo];
  output += `## ${tipo} (${items.length} keywords)\n\n`;

  // Tabla con headers
  output += `| # | Keyword | Subtipo | Fuente |\n`;
  output += `|---|---------|---------|--------|\n`;

  items.forEach((item, i) => {
    output += `| ${i + 1} | ${item.keyword} | ${item.subtipo} | ${item.source} |\n`;
  });

  output += `\n`;
}

output += `---\n`;
output += `\n🔍 = Google Suggest | 🤖 = OpenAI | 🔍🤖 = Ambas fuentes\n`;
output += `\n*Generado con Google Suggest API (expansión A-Z) + OpenAI GPT-4o-mini*`;

return [{
  json: {
    output: output
  }
}];
